package weeklytest

import "context"

// FallbackGenerator выдаёт проверенный резервный экзамен, чтобы интерфейс не
// ломался без ключа или при временном исчерпании бесплатного лимита Groq.
type FallbackGenerator struct{}

func (FallbackGenerator) Generate(context.Context, GenerationContext) (Generated, error) {
	return Generated{
		Title:  "Экзамен по защите от мошенников",
		Intro:  "20 практических ситуаций: фишинг, звонки, поддельная поддержка, платежи и социальная инженерия.",
		Source: SourceFallback,
		Questions: []Question{
			question("Покупатель прислал ссылку «для получения оплаты» и просит ввести данные карты. Что делать?", []string{"Открыть ссылку и проверить сумму", "Ввести только номер карты", "Не переходить и продолжить общение внутри площадки", "Переслать ссылку знакомому"}, 2, "Для получения денег не нужны CVC, срок действия карты или код из SMS. Сторонняя ссылка — типичный фишинг.", "phishing_link", DifficultyEasy),
			question("«Сотрудник поддержки» просит назвать код из SMS для отмены операции. Как поступить?", []string{"Продиктовать, если он знает имя", "Завершить разговор и самому открыть официальный канал поддержки", "Назвать половину кода", "Попросить перезвонить"}, 1, "Код подтверждения нельзя сообщать никому. Настоящая поддержка его не запрашивает.", "otp_theft", DifficultyEasy),
			question("Продавец видеокарты обещает скидку только при переводе напрямую на карту. Что безопаснее?", []string{"Перевести небольшой аванс", "Согласиться из-за старого профиля", "Попросить фото паспорта", "Оплатить защищённой сделкой площадки или отказаться"}, 3, "Профиль и документы можно подделать. Защищённая оплата сохраняет возможность спора.", "prepayment", DifficultyMedium),
			question("Звонящий из «банка» торопит перевести деньги на безопасный счёт. Как действовать?", []string{"Выполнить перевод частями", "Положить трубку и самому позвонить по номеру с карты", "Попросить прислать реквизиты в мессенджер", "Проверить, знает ли он остаток"}, 1, "Безопасных счетов для спасения денег не существует. Звонок проверяют только по официальному номеру.", "safe_account", DifficultyEasy),
			question("Для возврата денег вам прислали QR-код. Какое действие безопасно?", []string{"Сканировать камерой без ввода данных", "Открыть на другом телефоне", "Проверить возврат только внутри официального приложения", "Попросить новый QR-код"}, 2, "QR-код может скрывать фишинговую ссылку или платёж. Возврат оформляют через официальный интерфейс.", "qr_phishing", DifficultyMedium),
			question("В адресе входа написано avit0-pay.example вместо официального домена. Что это означает?", []string{"Технический домен оплаты", "Опечатку браузера", "Вероятную подмену домена", "Региональную версию сайта"}, 2, "Замена буквы цифрой и чужой домен — признаки тайпсквоттинга и кражи учётных данных.", "domain_spoofing", DifficultyMedium),
			question("Друг просит срочно занять деньги с нового аккаунта в мессенджере. Что делать?", []string{"Перевести небольшую сумму", "Проверить просьбу звонком по ранее известному номеру", "Попросить фото документа", "Спросить секретное слово в том же чате"}, 1, "Аккаунт могли взломать. Нужна проверка по независимому, заранее известному каналу.", "account_takeover", DifficultyEasy),
			question("Работодатель предлагает доход за приём переводов на вашу карту и отправку дальше. В чём риск?", []string{"Только в банковской комиссии", "Можно стать денежным посредником преступников", "Риск есть лишь без договора", "Нужно просто платить налог"}, 1, "Так вербуют дропперов. Через карту могут проводить украденные деньги, а ответственность ляжет на владельца.", "money_mule", DifficultyHard),
			question("Мастер просит установить программу удалённого доступа для возврата денег. Что правильно?", []string{"Установить и закрыть банковское приложение", "Дать доступ только на пять минут", "Отказаться и обратиться в организацию самостоятельно", "Скрыть пароли перед подключением"}, 2, "Удалённый доступ позволяет видеть экран и управлять устройством. Финансовые организации так возвраты не оформляют.", "remote_access", DifficultyMedium),
			question("На почту пришёл счёт с вложением invoice.exe. Как поступить?", []string{"Запустить в песочнице", "Переименовать в PDF", "Не открывать и проверить счёт через официальный кабинет", "Отправить файл продавцу обратно"}, 2, "Исполняемый файл может быть вредоносным. Счета проверяют в доверенном сервисе, а не через неожиданное вложение.", "malware_attachment", DifficultyMedium),
			question("Инвестиционный канал гарантирует 30% прибыли в неделю и просит перевести криптовалюту. Главный признак обмана?", []string{"Использование криптовалюты", "Гарантированная высокая доходность без риска", "Общение в канале", "Наличие отзывов"}, 1, "Гарантированная сверхдоходность и давление на быстрый перевод характерны для инвестиционных мошенников.", "investment_scam", DifficultyEasy),
			question("После знакомства в сети человек просит оплатить билет, но избегает видеосвязи. Что безопаснее?", []string{"Оплатить половину", "Попросить паспорт", "Не переводить деньги и прекратить финансовые просьбы", "Купить билет по присланной ссылке"}, 2, "Эмоциональное доверие используют в романтических схемах. Документы и истории легко подделываются.", "romance_scam", DifficultyMedium),
			question("Курьер просит сообщить код из SMS «для подтверждения доставки». Что делать?", []string{"Сообщить после получения посылки", "Проверить назначение кода в тексте SMS и никому его не сообщать", "Назвать последние две цифры", "Переслать скрин без номера телефона"}, 1, "В тексте SMS обычно указано, что код подтверждает вход или операцию. Курьеру он не нужен.", "delivery_otp", DifficultyMedium),
			question("В поиске первым показан рекламный сайт поддержки банка. Можно ли доверять номеру?", []string{"Да, реклама проверена поисковиком", "Да, если сайт использует HTTPS", "Нет, номер нужно брать из приложения или с карты", "Можно, если логотип правильный"}, 2, "Мошенники покупают рекламу и копируют сайты. HTTPS и логотип не доказывают принадлежность банку.", "fake_support", DifficultyHard),
			question("Сервис просит загрузить селфи с паспортом для получения подарка. Как оценить запрос?", []string{"Подарок оправдывает проверку", "Можно закрыть серию паспорта", "Не передавать документы без подтверждённой необходимости и официального сервиса", "Отправить фото низкого качества"}, 2, "Биометрия и паспортные данные ценны для мошенников. Сомнительная акция не является законной необходимостью.", "identity_theft", DifficultyMedium),
			question("Вам звонят голосом родственника и просят срочно перевести деньги после аварии. Как проверить?", []string{"Уточнить детали у звонящего", "Перезвонить родственнику и другим близким по известным номерам", "Перевести часть суммы", "Попросить голосовое сообщение"}, 1, "Голос можно подделать. Проверка должна идти по независимым каналам и через других близких.", "voice_deepfake", DifficultyHard),
			question("Покупатель прислал скриншот перевода, но денег в банковском приложении нет. Что делать?", []string{"Отдать товар из-за скриншота", "Попросить второй скриншот", "Проверить поступление в своём банке и не отдавать товар до зачисления", "Позвонить по номеру на чеке"}, 2, "Скриншот и уведомление можно подделать. Подтверждение — только фактическое зачисление в вашем приложении.", "fake_receipt", DifficultyMedium),
			question("Сайт просит войти через Госуслуги, но окно авторизации находится внутри неизвестного домена. Что безопасно?", []string{"Ввести логин без пароля", "Проверить адрес и открыть Госуслуги самостоятельно", "Продолжить, если есть замок", "Использовать другой браузер"}, 1, "Фишинговая форма может имитировать единый вход. Нужен официальный домен, открытый самостоятельно.", "oauth_phishing", DifficultyHard),
			question("После объявления о продаже вам предлагают перейти в Telegram, потому что «чат площадки не работает». Что делать?", []string{"Перейти, но не сообщать телефон", "Остаться в чате площадки и использовать её инструменты сделки", "Перейти после проверки профиля", "Попросить ссылку на другой мессенджер"}, 1, "Увод из защищённого чата лишает модерации и упрощает отправку фишинговых ссылок.", "off_platform", DifficultyMedium),
			question("Вы уже ввели пароль на подозрительном сайте. Какой порядок действий лучший?", []string{"Только закрыть вкладку", "Сначала написать владельцу сайта", "С официального устройства сменить пароль, завершить сессии и включить 2FA", "Подождать уведомления о входе"}, 2, "После фишинга нужно быстро сменить пароль через официальный сайт, отозвать сессии и защитить аккаунт вторым фактором.", "incident_response", DifficultyHard),
		},
	}, nil
}

func question(
	prompt string,
	options []string,
	correct int,
	explanation string,
	riskTag string,
	difficulty Difficulty,
) Question {
	return Question{
		Prompt: prompt, Options: options, CorrectIndex: correct,
		Explanation: explanation, RiskTag: riskTag, Difficulty: difficulty,
	}
}
